const result = $input.first().json.stdout;
if (!result) return [];
const lines = result.split('\n').filter(l => l.trim() !== '');
const EXT = /\.(jpg|jpeg|png|webp|gif)$/i;

function normalizeName(str) {
  if (!str) return '';
  return String(str).normalize("NFD").replace(/[\u0300-\u036f]/g, "").toUpperCase().replace(/[^A-Z0-9]/g, '');
}

const out = [];
for (const fullPath of lines) {
  if (!EXT.test(fullPath)) continue;

  const parts = fullPath.split('/');
  const fileName = parts.pop();
  const categoryRaw = parts.pop();

  if (!categoryRaw) continue;

  const category = normalizeName(categoryRaw);
  const baseName = fileName.replace(/\.[^.]+$/i, '');
  const matchKey = normalizeName(baseName);
  const compositeKey = matchKey + '|' + category;

  out.push({ 
    json: { 
      path: fullPath, 
      fileName, 
      categoryRaw, 
      category, 
      matchKey, 
      compositeKey 
    } 
  });
}

return out;

const items = $input.all();
const cleaned = [];

function normalizeName(str) {
  if (!str) return '';
  return String(str).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().replace(/[^A-Z0-9]/g, '');
}

const formatUsd = (val) => '$' + val.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' USD';
const formatCup = (val) => '$' + val.toLocaleString('en-US', { maximumFractionDigits: 0 }) + ' CUP';

for (const item of items) {
  const row = item.json;
  const nombre = row['PRODUCTO'] ? String(row['PRODUCTO']).trim() : '';
  if (!nombre) continue;

  const actualUsd = parseFloat(row['ACTUAL USD']) || 0;
  const actualCup = parseFloat(row['ACTUAL CUP']) || 0;
  const maxUsd = parseFloat(row['MAX HIST USD']) || 0;
  const maxCup = parseFloat(row['MAX HIST CUP']) || 0;

  // Lógica de Descuento: Evaluamos ambas monedas
  const hasDiscount = (maxUsd > actualUsd) && (maxCup > actualCup);

  let discountData = {};
  if (hasDiscount) {
      const diffUsd = maxUsd - actualUsd;
      const diffCup = maxCup - actualCup;
      discountData = {
          maxUsdFormatted: formatUsd(maxUsd),
          maxCupFormatted: formatCup(maxCup),
          diffUsdFormatted: formatUsd(diffUsd),
          diffCupFormatted: formatCup(diffCup)
      };
  }

  // Soporte para nueva estructura de categorías
  const categoryRaw = row['CATEGORIA_AUTO'] || row['CATEGORIA'] || 'General';

  cleaned.push({
    json: {
      matchKey: normalizeName(nombre),
      productId: nombre,
      usdPrice: actualUsd,
      cupPrice: actualCup,
      usdFormatted: formatUsd(actualUsd),
      cupFormatted: formatCup(actualCup),
      hasDiscount: hasDiscount,
      ...discountData,
      categoryRaw: categoryRaw
    }
  });
}
return cleaned;

function levenshtein(a, b) {
  if (a.length === 0) return b.length;
  if (b.length === 0) return a.length;
  const matrix = [];
  for (let i = 0; i <= b.length; i++) { matrix[i] = [i]; }
  for (let j = 0; j <= a.length; j++) { matrix[0][j] = j; }
  for (let i = 1; i <= b.length; i++) {
    for (let j = 1; j <= a.length; j++) {
      if (b.charAt(i - 1) === a.charAt(j - 1)) {
        matrix[i][j] = matrix[i - 1][j - 1];
      } else {
        matrix[i][j] = Math.min(
          matrix[i - 1][j - 1] + 1,
          Math.min(matrix[i][j - 1] + 1, matrix[i - 1][j] + 1)
        );
      }
    }
  }
  return matrix[b.length][a.length];
}

const unmatchedFiles = $input.all();
if (!unmatchedFiles || unmatchedFiles.length === 0) return [];

const allProducts = $node["CleanPricing"].all();
const recovered = [];

for (const file of unmatchedFiles) {
  const fileKey = file.json.matchKey || "";
  if (!fileKey) continue;

  let bestMatch = null;
  let bestSimilarity = 0;

  for (const product of allProducts) {
    const prodKey = product.json.matchKey || "";
    if (!prodKey) continue;

    const distance = levenshtein(fileKey, prodKey);
    const maxLength = Math.max(fileKey.length, prodKey.length);
    const similarity = maxLength === 0 ? 1 : (maxLength - distance) / maxLength;

    if (similarity >= 0.8 && similarity > bestSimilarity) {
      bestSimilarity = similarity;
      bestMatch = product.json;
    }
  }

  if (bestMatch) {
    recovered.push({
      json: {
        ...bestMatch,
        path: file.json.path,
        fileName: file.json.fileName,
        categoryRaw: file.json.categoryRaw
      }
    });
  }
}

return recovered;
